const items = $input.all();
const emailCount = items.length;

if (emailCount === 0) {
  return [{ json: { htmlDigest: '<p>No important emails today. Enjoy your evening!</p>', emailCount: 0, date: new Date().toISOString().split('T')[0] } }];
}

let summaries = '';
for (let i = 0; i < items.length; i++) {
  const email = items[i].json;
  const from = email.from || 'Unknown';
  const subject = email.subject || 'No Subject';
  const snippet = (email.snippet || email.textPlain || '').substring(0, 200);
  const time = email.date ? new Date(email.date).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }) : '';

  summaries += `<tr>
    <td style="padding:10px;border-bottom:1px solid #eee;">${i + 1}</td>
    <td style="padding:10px;border-bottom:1px solid #eee;"><strong>${from}</strong></td>
    <td style="padding:10px;border-bottom:1px solid #eee;">${subject}</td>
    <td style="padding:10px;border-bottom:1px solid #eee;color:#666;font-size:0.9em;">${snippet}...</td>
    <td style="padding:10px;border-bottom:1px solid #eee;">${time}</td>
  </tr>`;
}

const htmlDigest = `<div style="font-family:Arial,sans-serif;max-width:700px;margin:auto;">
  <h2 style="color:#2563eb;">Daily Email Digest</h2>
  <p style="color:#666;">Date: ${new Date().toISOString().split('T')[0]} | ${emailCount} important email(s)</p>
  <table style="width:100%;border-collapse:collapse;">
    <thead><tr style="background:#f3f4f6;"><th style="padding:10px;text-align:left;">#</th><th style="padding:10px;text-align:left;">From</th><th style="padding:10px;text-align:left;">Subject</th><th style="padding:10px;text-align:left;">Preview</th><th style="padding:10px;text-align:left;">Time</th></tr></thead>
    <tbody>${summaries}</tbody>
  </table>
</div>`;

return [{ json: { htmlDigest, emailCount, date: new Date().toISOString().split('T')[0] } }];
